#!/usr/bin/env bash
# Stage 2 of the reproduction: the computations behind the printed tables of ../paper/note.tex, in dependency order.
# Requires stage 1 (scripts/repro_run.sh): data/curves.parquet and results/optimal_{work,holdout,ext}.parquet, and the
# committed results/check_{work,holdout,ext}_summary.csv. The out-of-table curves are read from the committed
# results/oot_{1,2}.tsv (generated by scripts/out_of_table.gp under a time budget, so not regenerated here).
#    1. oot_convert.py                        results/oot_{1,2}.tsv -> results/oot_table.parquet (893 curves)
#    2. conj_check.py (out of table)          -> results/check_oot_summary.csv                     [tab:counts, last rows]
#    3. step10_sym2_euler.py <set> <k> <n>    -> results/sym2_<set>_<k>.parquet (Euler factors of Sym^2 at bad primes)
#    4. step10_rule.py <set>                  -> results/step10_rule_<set>_l{3,5,7,11,13}.parquet, _summary.csv
#    5. step11_tw_boundary.py                 -> results/step11_summary.csv, step11_ns3.csv,
#                                                tables/euler_uniform.tex [tab:uniform], tables/ns3.tex [tab:ns]
#    6. step12_tamagawa.py work               -> results/step12_work.csv (Section sec:tam; no printed table)
#    7. step6_local.py, step6_u1_fit.py work  -> results/local_primes.parquet, results/step6_u1_fit_work.txt
#       step7_twist2.py <work|holdout|ext>    -> results/step7_twist2_<set>_l<l>.parquet, results/step7_twist2_<set>.txt
#       step9_euler.py 3                      -> results/step9_euler_l3.txt (source of tables/euler_iso3.tex [tab:iso],
#                                                which was transcribed by hand and is not rewritten here)
#    8. make_tables.py                        -> tables/counts.tex [tab:counts], tables/isolated3.tex [tab:isolated],
#                                                tables/oot.tex [tab:oot], tables/twist.tex (not printed)
#    9. diff of the regenerated summaries and tables against the committed ones; scripts/selftest.py
# Outputs are written in place (results/, tables/); the committed versions are copied to the run directory first.
# Usage (from anywhere):  bash scripts/reproduce_tables.sh
# Environment: PYTHON (default python3), SHARDS_WORK (parallel shards of step 3 for the working set, default 3, as in
# the original run; the other ranges use one shard). Log: logs/reproduce_tables_<UTC time>/.
set -euo pipefail

PIPE="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$PIPE"
PYTHON=${PYTHON:-python3}; SHARDS_WORK=${SHARDS_WORK:-3}
RUN="$PIPE/logs/reproduce_tables_$(date -u +%Y%m%dT%H%M%SZ)"; mkdir -p "$RUN/ref/results" "$RUN/ref/tables"
LOG="$RUN/reproduce_tables.log"
exec > >(tee -a "$LOG") 2>&1
die() { echo "[tables] FAILED: $*"; exit 1; }
say() { echo "[tables] $(date -u +%H:%M:%S) $*"; }

say "pipeline directory: $PIPE"
say "log: $LOG"
"$PYTHON" -c "import numpy, pandas, pyarrow, cypari2; print('[tables] python', __import__('sys').version.split()[0], 'pandas', pandas.__version__, 'PARI (cypari2)', '.'.join(map(str, cypari2.Pari().version())))"
for f in data/curves.parquet results/optimal_work.parquet results/optimal_holdout.parquet results/optimal_ext.parquet \
         results/check_work_summary.csv results/check_holdout_summary.csv results/check_ext_summary.csv results/oot_1.tsv results/oot_2.tsv; do
  [ -e "$f" ] || die "missing $f (run scripts/repro_run.sh first)"
done

RESULTS="check_oot_summary.csv step10_rule_work_summary.csv step10_rule_holdout_summary.csv step10_rule_ext_summary.csv
         step10_rule_oot_summary.csv step11_summary.csv step11_ns3.csv step12_work.csv step9_euler_l3.txt
         step7_twist2_work.txt step7_twist2_holdout.txt step7_twist2_ext.txt step6_u1_fit_work.txt"
TABLES="euler_uniform.tex ns3.tex counts.tex isolated3.tex oot.tex twist.tex euler_iso3.tex"
for f in $RESULTS; do cp "results/$f" "$RUN/ref/results/"; done
for f in $TABLES; do cp "tables/$f" "$RUN/ref/tables/"; done

# 1-2. out-of-table curves
say "oot_convert.py"
"$PYTHON" scripts/oot_convert.py
"$PYTHON" -c "import sys, pandas as pd; n = len(pd.read_parquet('results/oot_table.parquet')); print('[tables] out-of-table curves', n); sys.exit(0 if n == 893 else '[tables] FAILED: expected 893 out-of-table curves')"
say "conj_check.py oot"
"$PYTHON" scripts/conj_check.py results/oot_table.parquet --nmax 4000000 --out results/check_oot 2>&1 | sed '/Warning/d'

# 3. symmetric-square Euler factors (stale shards are removed: step10_rule.py reads every results/sym2_<set>_*.parquet)
for s in work holdout ext oot; do
  n=1; [ "$s" = work ] && n=$SHARDS_WORK
  rm -f results/sym2_"$s"_*.parquet
  say "step10_sym2_euler.py $s ($n shard(s))"
  pids=()
  for ((k = 0; k < n; k++)); do
    "$PYTHON" scripts/step10_sym2_euler.py "$s" "$k" "$n" > "$RUN/sym2_${s}_${k}.log" 2>&1 & pids+=($!)
  done
  for p in "${pids[@]}"; do wait "$p" || die "step10_sym2_euler.py $s (see $RUN/sym2_${s}_*.log)"; done
  cat "$RUN"/sym2_"$s"_*.log
done

# 4. the rule on each range
for s in work holdout ext oot; do say "step10_rule.py $s"; "$PYTHON" scripts/step10_rule.py "$s"; done

# 5-6. correction term and image statistics; Tamagawa factors
say "step11_tw_boundary.py"; "$PYTHON" scripts/step11_tw_boundary.py
say "step12_tamagawa.py work"; "$PYTHON" scripts/step12_tamagawa.py work

# 7. inputs of tab:iso and tab:isolated
say "step6_local.py"; "$PYTHON" scripts/step6_local.py
say "step6_u1_fit.py work"; "$PYTHON" scripts/step6_u1_fit.py work > results/step6_u1_fit_work.txt 2> "$RUN/step6_u1_fit_work.stderr"
for s in work holdout ext; do say "step7_twist2.py $s"; "$PYTHON" scripts/step7_twist2.py "$s" > "results/step7_twist2_$s.txt" 2> "$RUN/step7_twist2_$s.stderr"; done
say "step9_euler.py 3"; "$PYTHON" scripts/step9_euler.py 3 > /dev/null 2> "$RUN/step9_euler_l3.stderr"

# 8. tables written by make_tables.py
say "make_tables.py"; "$PYTHON" scripts/make_tables.py

# 9. comparison with the committed versions
fail=0
cmp_file() {   # $1 committed copy, $2 regenerated file
  if diff -u "$1" "$2"; then say "$2 IDENTICAL to the committed version"; else say "$2 DIFFERS from the committed version"; fail=1; fi
}
for f in $RESULTS; do
  if [ "$f" = step6_u1_fit_work.txt ]; then   # the committed file also holds stderr warnings: compare the counts only
    pat='^ +[^ ]+ +x[0-9]: n='
    if diff -u <(grep -E "$pat" "$RUN/ref/results/$f") <(grep -E "$pat" "results/$f"); then
      say "results/$f IDENTICAL to the committed version (configuration lines)"
    else say "results/$f DIFFERS from the committed version (configuration lines)"; fail=1; fi
  else
    cmp_file "$RUN/ref/results/$f" "results/$f"
  fi
done
for f in $TABLES; do cmp_file "$RUN/ref/tables/$f" "tables/$f"; done
say "selftest.py"
"$PYTHON" scripts/selftest.py > "$RUN/selftest.log" 2>&1 || { cat "$RUN/selftest.log"; die "selftest.py"; }
tail -1 "$RUN/selftest.log"
[ "$fail" -eq 0 ] || die "regenerated files differ from the committed ones (committed copies in $RUN/ref)"
say "OK: every printed table reproduced from the pinned data"
